# -*- coding: utf-8 -*-
"""前端构建合并：shared/*.js → index.html 生成区（方案 P2 阶段二 / W3）
====================================================================
此前的重复：esc / normalize / parseJsonLoose / removeCyclesTopo 在
`shared/`（唯一事实源）与 `index.html`（页面）各有一份，
p0/p1/p2 集成脚本里还有第三份。阶段一已把集成脚本收编到 shared/integrations/，
本脚本把最后一份——页面内联副本——也改为**生成区**：

    /* AP:BEGIN core.js#normalize · generated · DO NOT EDIT */
    function normalize(s) { … }
    /* AP:END core.js#normalize */

生成区内容由 shared/ 源文件按符号抽取（括号配对）后按标记行缩进重排，
页面调用点完全不变（仍是全局 normalize/esc/parseJsonLoose/removeCyclesTopo）。
行尾风格：读入统一按 LF 处理，写出时还原为文件原有样式（index.html 为 CRLF）。

用法：
    python scripts/gen_frontend_regions.py           # 刷新 index.html
    python scripts/gen_frontend_regions.py --check   # 只校验不写（verify_all / CI 用）
退出码：0 = 一致/已刷新；1 = 区域缺失、重复或内容漂移
"""
import re
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
INDEX = ROOT / "index.html"

# (shared 源文件, 符号名；None = 整模块, 区域 id)
REGIONS = [
    ("shared/safe-dom.js", "esc", "safe-dom.js#esc"),
    ("shared/core.js", "removeCyclesTopo", "core.js#removeCyclesTopo"),
    ("shared/core.js", "normalize", "core.js#normalize"),
    ("shared/core.js", "parseJsonLoose", "core.js#parseJsonLoose"),
    ("shared/store.js", None, "shared/store.js"),
]

BEGIN = "/* AP:BEGIN {id} · generated by scripts/gen_frontend_regions.py · DO NOT EDIT */"
END = "/* AP:END {id} */"


def extract_symbol(src, name):
    """按括号配对抽出 `function name(...) { ... }` 完整文本（含签名行）。"""
    m = re.search(r"function\s+" + re.escape(name) + r"\s*\(", src)
    if not m:
        return None
    i = src.index("{", m.end() - 1)
    depth, j = 0, i
    while j < len(src):
        if src[j] == "{":
            depth += 1
        elif src[j] == "}":
            depth -= 1
            if depth == 0:
                return src[m.start(): j + 1]
        j += 1
    return None


def reindent(text, indent):
    """先去掉公共前导空白，再按 indent 统一缩进（空行不缩进）。"""
    lines = text.split("\n")
    body = [l for l in lines if l.strip()]
    common = min((len(l) - len(l.lstrip()) for l in body), default=0)
    return "\n".join((" " * indent + l[common:]) if l.strip() else "" for l in lines)


def region_regex(rid):
    b = re.escape(BEGIN.format(id=rid))
    e = re.escape(END.format(id=rid))
    return re.compile(b + r"[ \t]*\n(.*?)\n[ \t]*" + e, re.DOTALL)


def expected_body(rid):
    rel, sym, _ = next(r for r in REGIONS if r[2] == rid)
    src = (ROOT / rel).read_text(encoding="utf-8")
    if sym is None:
        return src.rstrip("\n")
    fn = extract_symbol(src, sym)
    if fn is None:
        raise SystemExit(f"[REGION] {rel} 中找不到 function {sym}（区域 {rid}）")
    return fn.rstrip("\n")


def main():
    check = "--check" in sys.argv[1:]
    raw = INDEX.read_bytes()
    crlf = b"\r\n" in raw
    text = raw.decode("utf-8").replace("\r\n", "\n")  # 统一按 LF 处理

    problems, dirty = [], False
    for _rel, _sym, rid in REGIONS:
        rx = region_regex(rid)
        hits = list(rx.finditer(text))
        if len(hits) == 0:
            problems.append(f"区域缺失：{rid}")
            continue
        if len(hits) > 1:
            problems.append(f"区域重复 {len(hits)} 处：{rid}")
            continue
        # 期望内容按 BEGIN 标记行的缩进重排
        begin_line = text[: hits[0].start()].split("\n")[-1]
        indent = len(begin_line) - len(begin_line.lstrip())
        want = reindent(expected_body(rid), indent)
        got = hits[0].group(1)
        if got != want:
            if check:
                problems.append(f"内容漂移：{rid}")
            else:
                text = text[: hits[0].start(1)] + want + text[hits[0].end(1):]
                dirty = True
                print(f"refreshed · {rid}")

    if problems:
        print("[FRONTEND-REGION]")
        for p in problems:
            print("  - " + p)
        print("FAILED: 生成区与 shared/ 不一致（跑 `python scripts/gen_frontend_regions.py` 刷新）")
        sys.exit(1)

    if check:
        print(f"ALL GREEN · {len(REGIONS)} 个生成区与 shared/ 一致")
        return
    if dirty:
        out = text.replace("\n", "\r\n") if crlf else text
        INDEX.write_bytes(out.encode("utf-8"))
    print(f"ALL GREEN · {len(REGIONS)} 个生成区已与 shared/ 对齐（{INDEX.name}）")


if __name__ == "__main__":
    main()
